  "test": "import pytest
from opentelemetry.trace import SpanKind
from mcp.server.lowlevel.server import Server
from mcp_types import CallToolRequestParams
from .conftest import SpanCapture, connected_runner, Ctx, SrvT

@pytest.fixture
def server() -> SrvT:
    async def list_tools(ctx: Ctx, params: None):
        return []
    return Server(name="test-server", version="0.0.1")

async def _ok_tool(ctx: Ctx, params: CallToolRequestParams):
    return {"content": [], "isError": False}

@pytest.mark.anyio
async def test_target_attribute_on_tool_call(server: SrvT, spans: SpanCapture):
    server.add_request_handler("tools/call", CallToolRequestParams, _ok_tool)
    async with connected_runner(server) as (client, _):
        spans.clear()
        await client.send_raw_request("tools/call", {"name": "mytool", "arguments": {}})
    [span] = [s for s in spans.finished() if s.kind == SpanKind.SERVER]
    assert span.attributes is not None
    assert span.attributes["mcp.method.target"] == "mytool"

@pytest.mark.anyio
async def test_target_attribute_on_custom_method(server: SrvT, spans: SpanCapture):
    server.add_request_handler("custom/op", CallToolRequestParams, _ok_tool)
    async with connected_runner(server) as (client, _):
        spans.clear()
        await client.send_raw_request("custom/op", {"name": "thing", "arguments": {}})
    [span] = [s for s in spans.finished() if s.kind == SpanKind.SERVER]
    assert span.attributes is not None
    assert span.attributes["mcp.method.target"] == "thing"
